/* ============================================================
   DECATHLON ENGINE
   PDF extraction (R3 based), Cost Break Down merge,
   and Decathlon-specific UI wiring.
   Depends on: shared.js (homeView, requestUnlock)
   ============================================================ */
/* ============================================================
   DECATHLON — PDF EXTRACTION ENGINE
   ============================================================ */
const DECATHLON_TEMPLATE_B64 = "";

// Column x-boundaries (points, PDF user space) derived from the Decathlon BOM
// table header row (Part / Dsm Code / Model Code / Component / Item Code /
// Grid Value / Items / Qty / Unit / Comments).
const DECATHLON_COLUMNS = [
  { key: 'part',      max: 57.6 },
  { key: 'dsm',       max: 126.6 },
  { key: 'model',     max: 183.45 },
  { key: 'component', max: 305.25 },
  { key: 'itemCode',  max: 427.05 },
  { key: 'gridValue', max: 492.05 },
  { key: 'items',     max: 552.95 },
  { key: 'qty',       max: 593.55 },
  { key: 'unit',      max: 626.0 },
  { key: 'comments',  max: Infinity },
];
function classifyDecathlonColumn(x) {
  for (const c of DECATHLON_COLUMNS) if (x < c.max) return c.key;
  return 'comments';
}

const DECATHLON_SECTION_KEYWORDS = ['Fabrics', 'Legal Marking', 'Label', 'Labels', 'Graphic', 'Accessories', 'Sales Packaging', 'Transport Packaging'];
// "Label" and "Labels" are the same logical section — different tech packs
// use either spelling, and which one holds RFID/traceability content vs.
// print content also varies between tech packs. We key everything off
// whatever literal text the PDF uses, normalized to the singular "Label".
function normalizeDecathlonSectionName(name) {
  return name === 'Labels' ? 'Label' : name;
}
const DECATHLON_HEADER_LINE = 'Part Dsm Code Model Component Item Code Grid Value Items Qty Unit Comments';
// The authoritative marker for "this line starts a new R3 block" is the
// "(R3 Code: NNNNNN)" annotation — present on every block-title line we've
// seen, even when the rest of the line's format varies (missing year
// prefix, an inline reference number that ISN'T the R3, no trailing period,
// etc). We only use the surrounding text as a best-effort fallback for CC
// and product name if the reliable per-page document header can't be found.
const DECATHLON_R3_CODE_RE = /\(R3\s*Code:\s*(\d+)\)/i;
const DECATHLON_R3_FALLBACK_RE = /(?:\d{4}\s*:\s*)?(\d+)\s*-\s*(.+?)-\s*(\d+)\.\s*-/i;
const DECATHLON_QTY_RE = /^\d+(\.\d+)?$/;

// DSM code / Item Code are single bare tokens - strip ALL internal
// whitespace, not just leading/trailing, as a final safety net regardless
// of how the text was assembled (belt-and-suspenders alongside the
// no-space concatenation above).
function squashDecathlonCode(s) {
  return (s || '').toString().replace(/\s+/g, '');
}

// Parses the WHOLE tech pack in a single pass, capturing every R3 block it
// finds (not just one) — so extracting several R3s from the same file only
// costs one read of the PDF instead of one read per R3.
async function extractAllDecathlonBlocks(file, onProgress) {
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;

  // Document-level header (product name + CC) — read once from the
  // template's fixed per-page header row (e.g. "WAISTCOAT TRAP 100 116177"),
  // which is far more reliable than trying to parse it out of the R3
  // block-title line, whose format varies between tech packs.
  let docProductName = '', docCcNumber = '';

  const blocks = {}; // r3Code -> { productName, ccNumber, r3, sections }
  let currentBlock = null;
  let currentSection = null;
  let activeRow = null;

  function flushRow() {
    if (activeRow) {
      // Occasionally the PDF merges the Item Code cell onto the tail of the
      // Component cell as one text run (no gap between them). If Item Code
      // came back empty but Component ends in a bare 6-8 digit number, split
      // it back out.
      if (!activeRow.itemCode) {
        const m = activeRow.component.match(/^(.*\S)\s+(\d{6,8})$/);
        if (m) { activeRow.component = m[1]; activeRow.itemCode = m[2]; }
      }
      if (currentBlock && currentSection && currentBlock.sections[currentSection]) {
        currentBlock.sections[currentSection].push(activeRow);
      }
    }
    activeRow = null;
  }

  function freshSections() {
    // Transport Packaging is intentionally excluded — those items are never
    // used downstream (per current business rule), so we don't bother
    // collecting them at all. The section heading stays in
    // DECATHLON_SECTION_KEYWORDS so its rows still get recognized as their
    // own section and don't leak into the preceding Sales Packaging section.
    return { Fabrics: [], 'Legal Marking': [], Label: [], Graphic: [], Accessories: [], 'Sales Packaging': [] };
  }

  for (let p = 1; p <= pdf.numPages; p++) {
    onProgress && onProgress(p, pdf.numPages);
    const page = await pdf.getPage(p);
    const viewport = page.getViewport({ scale: 1 });
    const content = await page.getTextContent();

    // Combine each item's text-matrix with the viewport transform so coordinates
    // come out in consistent, human-reading-order page space (x left→right,
    // y top→bottom) regardless of the PDF page's internal /Rotate value.
    const allItems = content.items
      .map(it => {
        const tx = pdfjsLib.Util.transform(viewport.transform, it.transform);
        return { text: it.str, x: tx[4], y: tx[5] };
      })
      .filter(it => it.text.trim().length > 0);

    // The fixed per-page header (product name + CC number) lives above our
    // normal content zone (y <= 90) — read it once, from whichever page
    // finds it first.
    if (!docCcNumber) {
      const headerItems = allItems.filter(it => it.y > 15 && it.y <= 90);
      headerItems.sort((a, b) => a.y - b.y || a.x - b.x);
      const headerLines = [];
      for (const it of headerItems) {
        let line = headerLines.find(l => Math.abs(l.y - it.y) < 2.5);
        if (!line) { line = { y: it.y, items: [] }; headerLines.push(line); }
        line.items.push(it);
      }
      headerLines.sort((a, b) => a.y - b.y);
      if (headerLines.length) {
        const topLine = headerLines[0];
        topLine.items.sort((a, b) => a.x - b.x);
        const tokens = topLine.items.map(i => i.text);
        const last = (tokens[tokens.length - 1] || '').trim();
        if (/^\d+$/.test(last)) {
          docCcNumber = last;
          docProductName = tokens.slice(0, -1).join(' ').trim();
        }
      }
    }

    const items = allItems.filter(it => it.y > 70 && it.y < 560);

    // cluster into visual lines (ascending y = top-to-bottom reading order)
    items.sort((a, b) => a.y - b.y || a.x - b.x);
    const lines = [];
    for (const it of items) {
      let line = lines.find(l => Math.abs(l.y - it.y) < 2.5);
      if (!line) { line = { y: it.y, items: [] }; lines.push(line); }
      line.items.push(it);
    }
    lines.sort((a, b) => a.y - b.y);
    for (const l of lines) l.items.sort((a, b) => a.x - b.x);

    for (const line of lines) {
      const lineText = line.items.map(i => i.text).join(' ').trim().replace(/\s+/g, ' ');

      const codeMatch = lineText.match(DECATHLON_R3_CODE_RE);
      const fallbackMatch = !codeMatch ? lineText.match(DECATHLON_R3_FALLBACK_RE) : null;
      if (codeMatch || fallbackMatch) {
        flushRow();
        const r3 = codeMatch ? codeMatch[1] : fallbackMatch[3];
        let ccNumber = '', productName = '';
        if (docCcNumber) {
          ccNumber = docCcNumber;
          productName = docProductName;
        } else if (fallbackMatch) {
          ccNumber = fallbackMatch[1];
          productName = fallbackMatch[2].trim();
        } else {
          const m2 = lineText.match(/^(?:\d{4}\s*:\s*)?(\d+)\s*-/);
          if (m2) ccNumber = m2[1];
        }
        if (!blocks[r3]) {
          blocks[r3] = { productName, ccNumber, r3, sections: freshSections() };
        }
        currentBlock = blocks[r3];
        currentSection = null;
        continue;
      }

      const normalizedLine = normalizeDecathlonSectionName(lineText);
      if (DECATHLON_SECTION_KEYWORDS.includes(lineText)) {
        flushRow();
        currentSection = normalizedLine;
        continue;
      }
      if (lineText === DECATHLON_HEADER_LINE) continue;
      if (lineText === 'Code' && line.items.length === 1) continue;
      if (/^The Supplier undertakes/i.test(lineText)) {
        // trailing document-wide legal boilerplate on the final page — not
        // part of any section, and must not be glued onto the last open row
        flushRow();
        currentSection = null;
        continue;
      }
      if (/^BOM\s*-\s*Developpement$/i.test(lineText)) {
        // this always immediately precedes a new R3 block's title line —
        // reset here so it can never be glued onto the previous block's
        // last open row if the new block's title hasn't been reached yet
        flushRow();
        currentSection = null;
        continue;
      }

      if (!currentBlock || !currentSection) continue;

      // DSM code and Item Code are each meant to be a single contiguous
      // token (a bare number/code, never legitimately containing a space).
      // Some tech pack PDFs occasionally render one of these as two or more
      // separate text runs (e.g. a font/style change mid-run) at the exact
      // same line/column - concatenating those WITH an inserted space (as
      // every free-text column below correctly does, since real words there
      // do need the space) silently corrupts the code with a stray space in
      // the middle. That corrupted code then (a) fails to exact-match an
      // otherwise-present row in the price list, and (b) shows up wrong/
      // truncated in the Designation cell and its LEFT(...,10) DSM-code
      // formula. Every other column keeps the space-joined behavior.
      const NO_SPACE_COLS = new Set(['dsm', 'itemCode']);
      const cols = { part: '', dsm: '', model: '', component: '', itemCode: '', gridValue: '', items: '', qty: '', unit: '', comments: '' };
      for (const it of line.items) {
        const col = classifyDecathlonColumn(it.x);
        const sep = (cols[col] && !NO_SPACE_COLS.has(col)) ? ' ' : '';
        cols[col] = cols[col] + sep + it.text;
      }

      const qtyVal = cols.qty.trim();
      if (DECATHLON_QTY_RE.test(qtyVal)) {
        flushRow();
        activeRow = {
          part: cols.part.trim(), dsm: squashDecathlonCode(cols.dsm), model: cols.model.trim(),
          component: cols.component.trim(), itemCode: squashDecathlonCode(cols.itemCode),
          gridValue: cols.gridValue.trim(), items: cols.items.trim(),
          qty: qtyVal, unit: cols.unit.trim(), comments: cols.comments.trim(),
        };
      } else if (activeRow) {
        for (const k of Object.keys(cols)) {
          if (!cols[k]) continue;
          if (NO_SPACE_COLS.has(k)) {
            activeRow[k] = squashDecathlonCode(activeRow[k] + cols[k]);
          } else {
            activeRow[k] = (activeRow[k] ? activeRow[k] + ' ' : '') + cols[k];
          }
        }
      }
    }
  }
  flushRow();

  return blocks;
}

// Extracts a specific set of R3s from one tech pack, parsing the PDF only
// once regardless of how many R3s are requested. Returns per-R3 deduped
// data plus which requested R3s weren't found (with the full list of R3s
// that actually exist in the file, for a clear error message).
async function extractDecathlonR3sFromFile(file, r3List, onProgress) {
  const blocks = await extractAllDecathlonBlocks(file, onProgress);
  const found = Object.keys(blocks);
  const collected = [];
  const notFound = [];
  for (const r3 of r3List) {
    const block = blocks[r3];
    if (!block || !block.ccNumber) {
      notFound.push(r3);
      continue;
    }
    dedupeDecathlonSections(block.sections);
    collected.push(block);
  }
  return { collected, notFound, allR3sInFile: found };
}

function decathlonDesignation(row) {
  const parts = [row.dsm, row.model, row.component, row.itemCode].filter(v => v);
  return parts.join(' ');
}

function isDecathlonThreadPart(part) {
  return /thread/i.test(part || '');
}

// Zippers live inside Accessories, but different tech packs (even from the
// same buyer) label them differently:
//  - some prefix the Part with "Z" + a number, e.g. "Z1 - hand pocket
//    -chain", "Z2 - ventilation -Slider", "Z5 - Back hoodamovible zipper"
//  - others just say "front zip" / "pocket zipper" directly in the Part,
//    with no "Z" prefix at all
// Component text is more standardized supplier-code language (ZCOIL / ZVIS
// / ZCHAIN / ZPUL / ZCCP / SLID COIL...) regardless of how Part is worded,
// so it's checked too. Used to carve zipper rows out of Accessories so they
// keep following the old (DSM+Part) dedupe rule instead of the new
// full-row rule (see dedupeDecathlonSections).
function isDecathlonZipperPart(row) {
  const part = (row.part || '').trim();
  const component = (row.component || '').trim();
  if (/^Z\d*\s*-/i.test(part)) return true;                    // "Z1 - ...", "Z - ..."
  if (/\bzip(per)?\b/i.test(part)) return true;                 // "front zip", "pocket zipper"
  if (/^(ZCOIL|ZVIS|ZCHAIN|ZPUL|ZCCP)\b/i.test(component)) return true; // zip supplier codes
  if (/\bslid(er)?\s*coil\b/i.test(component)) return true;     // slider hardware
  return false;
}

// Seam tape and glue are fabric-adjacent consumables that tech packs
// sometimes file under Accessories (or, less often, Legal Marking/Label) -
// per business rule they always belong in the Fabrics section for costing,
// regardless of which section heading they were actually extracted under.
// Checked against both Part and Component text, same pattern as the
// zipper-detection above.
function isDecathlonSeamTapeOrGlue(row) {
  const text = `${row.part || ''} ${row.component || ''}`;
  return /seam\s*tape/i.test(text) || /\bglue\b/i.test(text);
}

// Moves every seam-tape/glue row found in any non-Fabrics section into
// Fabrics, in place. Run before section-specific dedupe rules are applied
// so a redirected row is deduped using Fabrics' own DSM+ItemCode rule, not
// its original section's rule - it is being treated as a full Fabrics item
// from this point on, not just physically relocated.
//
// NOTE (visible consequence, flagged rather than silently decided): once
// redirected, a seam tape/glue row picks up every other Fabrics-only rule
// too - Consumption is left blank, Unit is forced to "yd" regardless of the
// tech pack's own unit for that row, and it gets NO Component
// supplier/Unit price/Api marker from the price list (Fabrics rows are
// exempt from price-list lookups, same as any other Fabrics item). If
// seam tape/glue should keep its own unit or still be priced from the
// list, say so and this can be scoped down to "section placement only".
function redirectDecathlonFabricLikeItems(sections) {
  sections.Fabrics = sections.Fabrics || [];
  for (const name of Object.keys(sections)) {
    if (name === 'Fabrics') continue;
    const rows = sections[name] || [];
    const keep = [];
    for (const r of rows) {
      if (isDecathlonSeamTapeOrGlue(r)) sections.Fabrics.push(r);
      else keep.push(r);
    }
    sections[name] = keep;
  }
}

// Full-row signature for the "same DSM code" dedupe rule: two rows only
// count as duplicates if EVERY field matches, not just DSM+Part.
function decathlonRowSignature(r) {
  return [r.part, r.dsm, r.model, r.component, r.itemCode, r.gridValue, r.items, r.qty, r.unit, r.comments]
    .map(v => (v || '').toString().trim().toLowerCase())
    .join('\u0001');
}

// A row with no real content at all — every identifying field blank. This
// is a PDF-parsing artifact (e.g. a stray blank line misread as a new row)
// rather than a real BOM item. Filtered out before dedupe/pricing so it
// never occupies a sheet row or picks up a spurious "DSM is missing"
// comment — previously, unused section capacity beyond the real item count
// could get a ghost row like this written into it.
function isDecathlonGhostRow(r) {
  return [r.part, r.dsm, r.itemCode, r.component, r.gridValue].every(v => !v || !v.toString().trim());
}

// Dedupe rules (per business logic):
//  - Fabrics: a row is a duplicate only if BOTH its DSM code and its Item
//    Code match a row already kept — keep the first occurrence, drop the rest.
//  - Zippers (Accessories rows identified by isDecathlonZipperPart — Part
//    starting with "Z", the word "zip"/"zipper" in Part, or a recognized
//    zip-component supplier code) and the whole Sales Packaging section: a
//    row is a duplicate if its DSM code AND its Part (Type) match a row
//    already kept — the original rule, unchanged.
//  - Every other section (Legal Marking, Label, Graphic, and non-zipper
//    Accessories rows): when the DSM code matches a row already kept, the
//    two rows are only treated as duplicates if EVERY other field also
//    matches exactly. If anything else differs, both rows are kept.
//  - Thread items (Part containing "thread", e.g. "Thread Tape" or
//    "Thread // Needle") are collapsed to a single representative row
//    regardless of DSM/Part — which one survives doesn't matter. This takes
//    priority over both rules above.
function dedupeDecathlonSections(sections) {
  // Seam tape / glue always belongs in Fabrics - reassign before anything
  // else so it's deduped and priced as a Fabrics item from here on.
  redirectDecathlonFabricLikeItems(sections);
  // Ghost rows (no real content) never make it in, in any section.
  for (const name of Object.keys(sections)) {
    sections[name] = (sections[name] || []).filter(r => !isDecathlonGhostRow(r));
  }
  // "Box" items in Sales Packaging are skipped entirely per current
  // business rule.
  sections['Sales Packaging'] = (sections['Sales Packaging'] || []).filter(r => !/\bbox\b/i.test(r.part || ''));

  const seenFab = new Set();
  sections.Fabrics = (sections.Fabrics || []).filter(r => {
    const key = (r.dsm || '') + '\u0001' + (r.itemCode || '');
    if (seenFab.has(key)) return false;
    seenFab.add(key);
    return true;
  });

  const OTHER_SECTIONS = ['Legal Marking', 'Label', 'Graphic', 'Accessories', 'Sales Packaging'];
  for (const name of OTHER_SECTIONS) {
    const rows = sections[name] || [];
    const kept = [];
    const seenPairs = new Set();     // DSM+Part rule — zippers & Sales Packaging
    const seenFullRows = new Set();  // full-row rule — everything else
    let threadTaken = false;
    for (const r of rows) {
      if (isDecathlonThreadPart(r.part)) {
        if (threadTaken) continue;
        threadTaken = true;
        kept.push(r);
        continue;
      }
      const useDsmPartRule = name === 'Sales Packaging' || (name === 'Accessories' && isDecathlonZipperPart(r));
      if (useDsmPartRule) {
        const key = (r.dsm || '') + '\u0001' + (r.part || '');
        if (seenPairs.has(key)) continue;
        seenPairs.add(key);
        kept.push(r);
      } else {
        const key = decathlonRowSignature(r);
        if (seenFullRows.has(key)) continue;
        seenFullRows.add(key);
        kept.push(r);
      }
    }
    sections[name] = kept;
  }
  return sections;
}

function decathlonItemCount(data) {
  return Object.values(data.sections).reduce((s, rows) => s + rows.length, 0);
}

// The set of DSM codes across every section is what defines "the same BOM"
// for the purposes of deciding whether two R3s can share one costing tab.
function dsmSetForDecathlonData(data) {
  const set = new Set();
  for (const rows of Object.values(data.sections)) {
    for (const r of rows) if (r.dsm) set.add(r.dsm);
  }
  return set;
}
function dsmSetsEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const v of a) if (!b.has(v)) return false;
  return true;
}

/* ============================================================
   DECATHLON — COST BREAK DOWN MERGE ENGINE
   (reuses the generic Excel row/formula/merge utilities defined above)
   ============================================================ */
const DECATHLON_FORMULA_COLS = ['C', 'K', 'O', 'P', 'S', 'T', 'U'];
// Fixed per-section row capacities (per business rule): every generated tab
// has the exact same number of rows in every section regardless of how many
// items a given tech pack actually has, so each section's total-cost row
// (and everything below it) always lands on the same row number across
// every tab/file. Unused rows within a section's capacity are hidden, not
// deleted (see fillSectionDecathlon) - the formulas/SUM ranges below are
// baked into the template (Decathlon_Format.xlsx) to match these exact
// capacities: Fabrics 40, Legal Marking 15, Labels 15, Graphics 20,
// Accessories 60, Sales Packaging 15 (incl. the 4 fixed sample rows),
// Transport Packaging 10. If the template's row layout ever changes, these
// numbers (and the template) must be regenerated together.
const DECATHLON_SECTION_CONFIG = {
  Fabrics:              { headerRow: 11,  firstBlank: 12,  lastBlank: 51,  totalRow: 52,  descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  'Legal Marking':      { headerRow: 53,  firstBlank: 54,  lastBlank: 68,  totalRow: 69,  descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  Label:                { headerRow: 70,  firstBlank: 71,  lastBlank: 85,  totalRow: 86,  descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  Graphic:              { headerRow: 87,  firstBlank: 88,  lastBlank: 107, totalRow: 108, descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  Accessories:          { headerRow: 109, firstBlank: 110, lastBlank: 169, totalRow: 170, descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  'Sales Packaging':    { headerRow: 171, firstBlank: 172, lastBlank: 186, totalRow: 187, descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
  'Transport Packaging': { headerRow: 188, firstBlank: 189, lastBlank: 198, totalRow: 199, descCol: 2, formulaCols: DECATHLON_FORMULA_COLS },
};

// Same as fillSection(), but WITHOUT renumberSlNo — column A holds the
// Decathlon "Type" (Part) value, not a serial number, so it must never be
// overwritten with a running count.
//
// Any rows the template already has pre-filled (e.g. Sales Packaging's
// sample Blister poly / Carton / Carton sticker / Gumtape rows) are left
// completely untouched — extracted items are appended into the blank rows
// below them, and only that remaining capacity drives whether more rows
// need to be inserted.
function countExistingFilledRows(ws, first, last, descCol) {
  let count = 0;
  for (let r = first; r <= last; r++) {
    const v = ws.getCell(r, descCol).value;
    const isFilled = v !== null && v !== undefined && String(v).trim() !== '';
    if (!isFilled) break; // existing content is assumed contiguous from the top
    count++;
  }
  return count;
}

function fillSectionDecathlon(ws, cfg, items, maxSheetRow) {
  const descCol = cfg.descCol;
  const existingCount = countExistingFilledRows(ws, cfg.firstBlank, cfg.lastBlank, descCol);
  const first = cfg.firstBlank + existingCount;
  let last = cfg.lastBlank;
  const available = last - first + 1;
  const needed = items.length;
  const amount = Math.max(0, needed - available);

  const oldMerges = snapshotAndUnmergeAll(ws);
  const rowTemplateMerges = oldMerges
    .filter(m => m.minRow === cfg.firstBlank)
    .map(m => ({ minCol: m.minCol, maxCol: m.maxCol }));

  let insertAt = null;
  if (amount > 0) {
    insertAt = last;
    const blankRows = Array.from({ length: amount }, () => []);
    ws.spliceRows(insertAt, 0, ...blankRows);
    shiftWholeSheetFormulas(ws, insertAt, amount, maxSheetRow + amount, 27);
    for (let i = 0; i < amount; i++) {
      const newRow = insertAt + i;
      copyRowStyle(ws, insertAt + amount, newRow, 27);
      copyRowFormulas(ws, insertAt + amount, newRow, cfg.formulaCols);
    }
    maxSheetRow += amount;
    last += amount;
    cfg.totalRow += amount;
  }

  const UNIT_COL = 13; // column M — Per unit
  const INPUT_COLS = [1, 2, 6, 7, 8, 9, 10, 12, 13, 14, 17, 18, 22]; // A,B,F,G,H,I,J,L,M,N,Q,R,V
  items.forEach((item, i) => {
    const r = first + i;
    // Clear the whole row's input columns first so no stale template sample
    // data (or a stale style from a previous run, e.g. a red "Price not
    // found" font) survives into a freshly-written row.
    for (const col of INPUT_COLS) {
      const cell = ws.getCell(r, col);
      cell.value = null;
    }
    ws.getCell(r, descCol).value = item.extractedInfo;
    if (item.unit) ws.getCell(r, UNIT_COL).value = item.unit;
    if (cfg.extraCols) {
      for (const { col, compute, styleCompute } of cfg.extraCols) {
        const cell = ws.getCell(r, col);
        const val = compute(item, r);
        if (val !== null && val !== undefined) cell.value = val;
        if (styleCompute) {
          const font = styleCompute(item);
          // Assigning cell.font alone on a still-default (never individually
          // styled) cell can bleed into OTHER untouched cells that happen to
          // share that same default style reference in ExcelJS — confirmed
          // via direct reproduction. Assigning the whole .style object (not
          // just .font) forces this cell onto its own independent style
          // record instead, avoiding cross-cell contamination.
          if (font) cell.style = Object.assign({}, cell.style, { font: Object.assign({}, cell.font, font) });
        }
      }
    }
  });
  // Clear any leftover rows beyond what we just wrote (but never touch the
  // preserved existing rows above `first`).
  for (let r = first + items.length; r <= last; r++) {
    for (const col of INPUT_COLS) ws.getCell(r, col).value = null;
  }

  if (amount > 0) {
    remergeShifted(ws, oldMerges, insertAt, amount);
    for (let i = 0; i < amount; i++) {
      const newRow = insertAt + i;
      for (const pat of rowTemplateMerges) {
        mergeSectionRange(ws, newRow, pat.minCol, pat.maxCol - pat.minCol + 1);
      }
    }
  } else {
    remergeShifted(ws, oldMerges, 0, 0);
  }

  // Row-hiding is intentionally NOT done here. Sections are filled
  // bottom-to-top, so a section already filled (and hidden) can still be
  // physically shifted further down later, by a row-insertion in a
  // different section that sits ABOVE it in the sheet but is processed
  // AFTER it in this loop. ExcelJS's spliceRows does not carry a row's
  // `hidden` flag along when that happens (confirmed by direct testing) -
  // it stays pinned to its old row index while the content moves out from
  // under it. Hiding is therefore done in one final pass, after every
  // section's insertion is complete - see fillDecathlonWorksheet. The
  // coordinates below are "as of this call"; the caller adjusts them for
  // any later shift.
  return {
    maxSheetRow, totalRow: cfg.totalRow,
    hideRange: { firstBlank: cfg.firstBlank, first, itemsLength: items.length, last, headerRow: cfg.headerRow, totalRow: cfg.totalRow },
  };
}

// A "pce"-unit consumption gets a flat 2% uplift per current business rule
// (e.g. extracted qty 1 -> 1.02 in the Consumption cell). Fabrics are
// exempt because fabric consumption is never written at all (see below).
const DECATHLON_PCE_UPLIFT = 1.02;
function decathlonConsumptionValue(r) {
  const n = parseFloat(r.qty);
  if (isNaN(n)) return r.qty; // leave non-numeric qty untouched, as before
  if ((r.unit || '').trim().toLowerCase() === 'pce') {
    return Math.round(n * DECATHLON_PCE_UPLIFT * 1e6) / 1e6; // trim float noise
  }
  return n;
}

/* ============================================================
   PRICING ENGINE (Component supplier / Unit price / Api marker)
   ============================================================ */

// Known flat-rate categories — identified purely by Part-name keyword, and
// these ALWAYS win over a price-file lookup (no DSM/Item Code match needed
// at all) per current business rule. Order matters: the combined
// "Size+Care" check must be tried before the standalone Size/Care checks,
// though each standalone check also explicitly excludes the other keyword
// as a second safeguard.
// Interlining is sometimes labeled something else entirely in the Part
// column (e.g. "Thermofusing"), so it's identified by the constructed
// Designation text (which pulls in Component, e.g. "INTERLINING RPET/PET
// 55G / 160 CM") instead of Part — the material description reliably says
// "interlining" even when the Part/Type name doesn't.
function decathlonIsInterlining(r) {
  return /interlining/i.test(decathlonDesignation(r) || '');
}

const DECATHLON_FLAT_RATES = [
  // Thread (incl. Bartack, which shares the same thread material but
  // doesn't say "thread" in its own Part name) and Thread Textured (a
  // different DSM, still thread) — all covered by isDecathlonThreadPart.
  { test: r => isDecathlonThreadPart(r.part) || /bartack/i.test(r.part || ''), price: 0.00054, supplier: 'Coats BD' },
  { test: r => /rfid/i.test(r.part || ''), price: 0.055, supplier: 'Checkpoint' },
  { test: r => /size/i.test(r.part || '') && /care/i.test(r.part || '') && /label/i.test(r.part || ''), price: 0.058, supplier: 'Blazon' },
  { test: r => /size/i.test(r.part || '') && /label/i.test(r.part || '') && !/care/i.test(r.part || ''), price: 0.014, supplier: 'Blazon' },
  { test: r => /care/i.test(r.part || '') && /label/i.test(r.part || '') && !/size/i.test(r.part || ''), price: 0.044, supplier: 'Blazon' },
  // Handles both "traceability" and the tech pack's own "TRACABILITY" spelling.
  { test: r => /trac\w*abilit/i.test(r.part || ''), price: 0.014, supplier: 'Snowtex' },
  // Interlining is a Fabrics-section item and gets priced despite the
  // otherwise blanket "no pricing in Fabrics" rule — confirmed exception.
  { test: r => decathlonIsInterlining(r), price: 0.23, supplier: 'Osman' },
];
function decathlonFlatRateFor(r) {
  return DECATHLON_FLAT_RATES.find(f => f.test(r)) || null;
}

function decathlonNormalizeOrigin(s) {
  const t = (s || '').toString().trim().toLowerCase();
  if (t.startsWith('bangla') || t === 'bd' || t === 'bgd') return 'bangladesh';
  if (t.includes('china') || t === 'prc' || t === 'cn') return 'china';
  if (t.includes('vietnam') || t.includes('viet nam') || t === 'vn') return 'vietnam';
  return t;
}
function decathlonNormalizeCurrency(s) {
  const t = (s || '').toString().trim().toLowerCase();
  if (t === 'usd' || t === 'us$' || t === '$') return 'usd';
  if (t === 'cny' || t === 'rmb' || t === '¥') return 'cny';
  return t;
}

// Robust price parser: a plain `parseFloat` fails (returns NaN) on
// anything with currency symbols, thousands-separator commas, a trailing
// unit/currency suffix, or surrounding whitespace - e.g. "$10.00",
// "1,234.56", "10.00 USD", "(10.00)" for a negative. SheetJS's raw:false
// read (used deliberately so DSM/Item codes aren't numerically
// reinterpreted - see parseDecathlonPriceFile) returns each cell's
// FORMATTED display text, so a Price cell with ANY number format beyond
// plain digits comes through exactly like that, even though it looks like
// an ordinary number when the file is opened in Excel. A row whose price
// fails to parse is silently dropped by buildDecathlonPriceIndex before it
// ever reaches the region-priority lookup - which is exactly how a
// correctly-spelled, correctly-currency'd Bangladesh row can vanish
// without a trace and let a lower-priority region win unnoticed.
function parseDecathlonPrice(raw) {
  if (raw === null || raw === undefined) return NaN;
  let s = raw.toString().trim();
  if (!s) return NaN;
  let negative = false;
  if (/^\(.*\)$/.test(s)) { negative = true; s = s.slice(1, -1); }
  s = s.replace(/[^0-9.]/g, ''); // strip currency symbols, commas, unit suffixes, spaces
  if (!s) return NaN;
  const n = parseFloat(s);
  if (isNaN(n)) return NaN;
  return negative ? -n : n;
}

// Builds a DSM+ItemCode -> [{origin, currency, price, rawPrice, supplier}]
// index from the raw rows of the uploaded price list. Rows missing DSM or
// Item Code are skipped (there's no way to key them at all); a row with an
// unparseable price is intentionally KEPT (with price left as NaN, and the
// original text preserved in rawPrice) rather than silently dropped -
// decathlonLookupPrice checks for exactly this, so a higher-priority
// region with a real but unparseable price is flagged instead of the
// lookup just proceeding as if that region had no entry at all.
function buildDecathlonPriceIndex(rawRows) {
  const idx = new Map();
  for (const row of rawRows) {
    const dsm = squashDecathlonCode(row.dsm);
    const itemCode = squashDecathlonCode(row.itemCode);
    if (!dsm || !itemCode) continue;
    const price = parseDecathlonPrice(row.price);
    const key = dsm + '\u0001' + itemCode;
    const entry = {
      origin: decathlonNormalizeOrigin(row.origin),
      currency: decathlonNormalizeCurrency(row.currency),
      price,
      rawPrice: (row.price === null || row.price === undefined) ? '' : row.price.toString().trim(),
      supplier: (row.supplier || '').toString().trim(),
    };
    if (!idx.has(key)) idx.set(key, []);
    idx.get(key).push(entry);
  }
  return idx;
}

const DECATHLON_CNY_TO_USD = 0.15;
const DECATHLON_REGION_PRIORITY = ['bangladesh', 'china', 'vietnam'];

// Looks up a DSM+ItemCode pair in the price index, walking regions in
// priority order (Bangladesh -> China -> Vietnam) and, within each region,
// preferring a USD-priced row over a CNY-priced one (converted at 0.15).
// Returns { price, supplier, region } or null if no match anywhere.
function decathlonLookupPrice(priceIndex, dsm, itemCode) {
  if (!priceIndex) return null;
  // Squash internal whitespace here too (not just at extraction time) so a
  // stray space anywhere in either the extracted row or the uploaded price
  // list itself can never by itself cause an otherwise-real match to be
  // missed.
  const key = squashDecathlonCode(dsm) + '\u0001' + squashDecathlonCode(itemCode);
  const entries = priceIndex.get(key);
  if (!entries || !entries.length) return null;

  // If the price list has ANY entry for this item under an Origin that
  // doesn't normalize to one of the 3 known regions, it can't safely be
  // ranked against the regions that DO match below - it might be a variant
  // spelling of a higher-priority region (e.g. "BD - Chittagong" instead
  // of "Bangladesh") that would have outranked whatever's about to be
  // picked. This must be checked BEFORE walking the priority order below,
  // not after: checking only after a lower-priority region already
  // returned is exactly how this bug happened (an unrecognized-Origin
  // Bangladesh row was silently outranked by a correctly-recognized China
  // row). Flagged rather than guessed at.
  const unknownOrigins = [...new Set(entries.map(e => e.origin).filter(o => !DECATHLON_REGION_PRIORITY.includes(o)))];
  if (unknownOrigins.length) return { unrecognizedOrigin: unknownOrigins[0] };

  for (const region of DECATHLON_REGION_PRIORITY) {
    const regionEntries = entries.filter(e => e.origin === region);
    if (!regionEntries.length) continue;
    const usd = regionEntries.find(e => e.currency === 'usd' && !isNaN(e.price));
    if (usd) return { price: usd.price, supplier: usd.supplier, region };
    const cny = regionEntries.find(e => e.currency === 'cny' && !isNaN(e.price));
    if (cny) return { price: Math.round(cny.price * DECATHLON_CNY_TO_USD * 1e6) / 1e6, supplier: cny.supplier, region };
    // This region DOES have a price-list entry for this DSM+Item Code, so
    // it must never be silently skipped in favor of a lower-priority
    // region. Two distinct ways that can happen: the currency isn't one we
    // convert (handled below), or the currency IS recognized but the price
    // itself didn't parse to a real number (e.g. "$10.00", "1,234.56" -
    // see parseDecathlonPrice) - both get their own explicit flag rather
    // than silently falling through.
    const recognizedCurrencyEntry = regionEntries.find(e => e.currency === 'usd' || e.currency === 'cny');
    if (recognizedCurrencyEntry) {
      return { unmatchedRegion: region, invalidPrice: true, rawPrice: recognizedCurrencyEntry.rawPrice };
    }
    return { unmatchedRegion: region, rawCurrency: regionEntries[0].currency };
  }
  return null;
}

const DECATHLON_RED_FONT = { color: { argb: 'FFCC0000' } };
const DECATHLON_DEFAULT_FONT = { color: { argb: 'FF000000' } };

// Decides what (if anything) goes in Component supplier / Unit price / Api
// marker for one extracted row. Returns null when the row should be left
// completely untouched (non-Interlining Fabrics rows — rule 3).
//  1. Fabrics (except Interlining) -> untouched.
//  2. Flat-rate categories (rule 10) -> always win, no price-file lookup.
//  3. No DSM code -> "DSM is missing" in red, no price.
//  4. DSM+Item Code price-file lookup, Bangladesh -> China -> Vietnam,
//     USD preferred over CNY (converted). No match anywhere -> "Price not
//     found" in red. A higher-priority region's entry is NEVER silently
//     skipped in favor of a lower-priority one: if it exists but its
//     currency or origin text isn't recognized, that's reported explicitly
//     in red instead (see decathlonLookupPrice).
//  5. A match sourced from China or Vietnam gets an Api marker formula
//     (Total Local price * 15%); Bangladesh does not.
function computeDecathlonPricing(r, sectionName, priceIndex) {
  const isFabric = sectionName === 'Fabrics';
  const isInterlining = decathlonIsInterlining(r);
  if (isFabric && !isInterlining) return null;

  const flat = decathlonFlatRateFor(r);
  if (flat) {
    return { supplierText: flat.supplier, isError: false, unitPrice: flat.price, needsApiMarker: false };
  }

  if (!r.dsm) {
    return { supplierText: 'DSM is missing', isError: true, unitPrice: null, needsApiMarker: false };
  }

  const found = decathlonLookupPrice(priceIndex, r.dsm, r.itemCode);
  if (!found) {
    return { supplierText: 'Price not found', isError: true, unitPrice: null, needsApiMarker: false };
  }
  if (found.unmatchedRegion) {
    const msg = found.invalidPrice
      ? `${found.unmatchedRegion} price found, not a valid number ("${found.rawPrice}")`
      : `${found.unmatchedRegion} price found, unrecognized currency "${found.rawCurrency}"`;
    return { supplierText: msg, isError: true, unitPrice: null, needsApiMarker: false };
  }
  if (found.unrecognizedOrigin) {
    return { supplierText: `Price found, unrecognized origin "${found.unrecognizedOrigin}"`, isError: true, unitPrice: null, needsApiMarker: false };
  }
  return {
    supplierText: found.supplier,
    isError: false,
    unitPrice: found.price,
    needsApiMarker: found.region !== 'bangladesh',
  };
}

// Parses the uploaded price list (large flat table: DSM Code, Item Code,
// Price, Unit, Currency, Supplier, Origin) into raw row objects for
// buildDecathlonPriceIndex. Uses array-of-arrays mode (faster than SheetJS's
// default object mode) since the file can be hundreds of thousands of rows.
// Column order isn't assumed — matched by header text so a reordered sheet
// still works.
async function parseDecathlonPriceFile(file) {
  const buf = await file.arrayBuffer();
  const wb = XLSX.read(buf, { type: 'array' });
  const ws = wb.Sheets[wb.SheetNames[0]];
  // raw:false reads each cell's formatted display text rather than its raw
  // numeric value — DSM/Item codes are ID-like strings, and reading them as
  // numbers risks silent reinterpretation (e.g. dropped leading zeros) if
  // Excel happens to store them as a numeric type. Price still parses fine
  // as text via parseFloat downstream.
  const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: '' });
  if (!aoa.length) return [];
  const header = aoa[0].map(h => (h || '').toString().trim().toLowerCase());
  const idxOf = name => header.indexOf(name);
  const c = {
    dsm: idxOf('dsm code'),
    itemCode: idxOf('item code'),
    price: idxOf('price'),
    unit: idxOf('unit'),
    currency: idxOf('currency'),
    supplier: idxOf('supplier'),
    origin: idxOf('origin'),
  };
  const missing = Object.entries(c).filter(([, i]) => i === -1).map(([k]) => k);
  if (missing.length) throw new Error(`Price list is missing expected column(s): ${missing.join(', ')}`);

  const rows = [];
  for (let i = 1; i < aoa.length; i++) {
    const row = aoa[i];
    if (!row || !row.length) continue;
    rows.push({
      dsm: row[c.dsm], itemCode: row[c.itemCode], price: row[c.price],
      unit: row[c.unit], currency: row[c.currency], supplier: row[c.supplier], origin: row[c.origin],
    });
  }
  return rows;
}


// r3List is the full set of R3 numbers that share this exact BOM (see
// buildMultiCCCostBreakDown) — when there's more than one, they all go into
// the R3 cell together, comma-separated, instead of getting separate tabs.
// Returns per-section item counts.
function fillDecathlonWorksheet(ws, extracted, r3List, priceIndex) {
  const { productName, ccNumber, r3, sections } = extracted;
  const originalRowCount = ws.rowCount;
  let maxRow = originalRowCount;
  normalizeFormulas(ws, maxRow, 27);

  if (productName) ws.getCell('B1').value = productName;

  // CC and R3 are written as real numbers (not strings) so Excel doesn't
  // flag them with a "number stored as text" warning. A merged R3 cell
  // (multiple R3s sharing one BOM) can't be a single number, so it falls
  // back to a comma-separated text list in that case only.
  if (ccNumber !== undefined && ccNumber !== null && ccNumber !== '') {
    const ccNum = Number(ccNumber);
    ws.getCell('B2').value = Number.isFinite(ccNum) ? ccNum : String(ccNumber);
  }
  const r3s = ((r3List && r3List.length) ? r3List : [r3]).filter(Boolean);
  if (r3s.length === 1) {
    const r3Num = Number(r3s[0]);
    ws.getCell('B4').value = Number.isFinite(r3Num) ? r3Num : String(r3s[0]);
  } else if (r3s.length > 1) {
    ws.getCell('B4').value = r3s.join(', ');
  }

  const toItems = (rows, sectionName) => {
    const isFabric = sectionName === 'Fabrics';
    return rows.map(r => ({
      extractedInfo: decathlonDesignation(r),
      // Fabrics always report in yd regardless of what the tech pack's own
      // unit column says — consumption isn't filled for fabrics at all
      // (see qty below), so there's no conversion to do here, just the
      // fixed unit label.
      unit: isFabric ? 'yd' : r.unit,
      type: r.part,
      // Fabric consumption is intentionally left blank (extraCols below
      // skips writing when qty is null/undefined). Every other section
      // gets its normal consumption, with a 2% uplift on "pce" units.
      qty: isFabric ? null : decathlonConsumptionValue(r),
      // null for non-Interlining Fabrics rows -> supplier/price/Api marker
      // extraCols below all no-op for those, leaving the cells untouched.
      pricing: computeDecathlonPricing(r, sectionName, priceIndex),
      // Length of the row's own (already-squashed) DSM code - drives the
      // column C DSM-code formula override below.
      dsmLen: squashDecathlonCode(r.dsm).length,
    }));
  };
  const extraCols = [
    { col: 1, compute: it => it.type },
    {
      // C — DSM code, recomputed from the Designation text via
      // LEFT(B,N). The template's own row formula is already
      // "=LEFT(B{row},10)", correct for the (default, majority) 10-digit
      // DSM codes seen in tech packs, and is left completely untouched for
      // those. The only other length actually used is 7 digits, in which
      // case this row's formula is overridden to LEFT(B{row},7) instead -
      // any other/unexpected length falls back to the unchanged default,
      // same as today.
      col: 3,
      compute: (it, r) => (it.dsmLen === 7) ? { formula: `LEFT(B${r},7)` } : null,
    },
    { col: 12, compute: it => it.qty }, // null/undefined -> cell left untouched
    {
      col: 6, // Component supplier — supplier name, or a "DSM is missing" /
               // "Price not found" comment in red when pricing failed.
      compute: it => (it.pricing ? it.pricing.supplierText : null),
      styleCompute: it => (it.pricing ? (it.pricing.isError ? DECATHLON_RED_FONT : DECATHLON_DEFAULT_FONT) : null),
    },
    {
      col: 9, // Unit price — always a real number, never text.
      compute: it => (it.pricing && it.pricing.unitPrice !== null && it.pricing.unitPrice !== undefined) ? it.pricing.unitPrice : null,
    },
    {
      col: 22, // Api marker — formula, only for China/Vietnam-sourced prices.
      compute: (it, r) => (it.pricing && it.pricing.needsApiMarker) ? { formula: `S${r}*0.15` } : null,
    },
  ];

  // Bottom-to-top through the sheet so inserting rows in a lower section
  // never shifts a section still queued for processing above it.
  const order = ['Transport Packaging', 'Sales Packaging', 'Accessories', 'Graphic', 'Label', 'Legal Marking', 'Fabrics'];
  const counts = {};
  const hideJobs = []; // { hideRange, maxRowAfter } per section, in processing order
  for (const name of order) {
    const cfg = { ...DECATHLON_SECTION_CONFIG[name], extraCols };
    const rows = sections[name] || [];
    counts[name] = rows.length;
    const result = fillSectionDecathlon(ws, cfg, toItems(rows, name), maxRow);
    maxRow = result.maxSheetRow;
    hideJobs.push({ hideRange: result.hideRange, maxRowAfter: maxRow });
  }

  // Apply row visibility in one final pass, now that every section's row
  // insertion (if any) is finished. A section processed earlier in the
  // loop above can still be shifted further down afterwards, by a later
  // section that sits above it in the sheet needing its own insertion -
  // `maxRowFinal - maxRowAfter` is exactly that additional shift for each
  // section (maxRow only ever grows, monotonically, across the loop). See
  // the comment on fillSectionDecathlon's return value for why this can't
  // just be done inline, section by section.
  const maxRowFinal = maxRow;
  for (const { hideRange, maxRowAfter } of hideJobs) {
    const shift = maxRowFinal - maxRowAfter;
    const { firstBlank, first, itemsLength, last, headerRow, totalRow } = hideRange;
    for (let r = firstBlank + shift; r < first + shift; r++) ws.getRow(r).hidden = false; // static pre-filled rows
    for (let r = first + shift; r < first + itemsLength + shift; r++) ws.getRow(r).hidden = false; // this run's items
    for (let r = first + itemsLength + shift; r <= last + shift; r++) ws.getRow(r).hidden = true;  // unused capacity
    ws.getRow(headerRow + shift).hidden = false;
    ws.getRow(totalRow + shift).hidden = false;
  }

  // "Local Transport" (row 226, col I in the template) gets the sum of
  // every Api marker formula written across the sheet (col V). Row 226 sits
  // below every BOM section, so if any section needed row insertion it
  // shifts down by the same cumulative amount as the sheet as a whole —
  // computed here from how much maxRow grew versus the sheet's original
  // row count. The sum range's top (row 11, the Fabrics header) never
  // shifts since nothing sits above it; only the bottom does.
  const totalRowShift = maxRow - originalRowCount;
  const LOCAL_TRANSPORT_ROW = 226;
  const API_MARKER_TOP_ROW = 11;
  const API_MARKER_BOTTOM_ROW = 199; // Transport Packaging's total row, original coordinates
  const localTransportRow = LOCAL_TRANSPORT_ROW + totalRowShift;
  const apiMarkerBottomRow = API_MARKER_BOTTOM_ROW + totalRowShift;
  ws.getCell(localTransportRow, 9).value = { formula: `SUM(V${API_MARKER_TOP_ROW}:V${apiMarkerBottomRow})` };

  return counts;
}

// Full manual worksheet clone (ExcelJS has no cross-sheet "duplicate" API):
// copies every cell's value/style/number-format plus column widths, row
// heights, merges, data-validation dropdowns and view settings from
// sourceWs into a brand-new sheet in targetWorkbook.
function cloneWorksheetInto(targetWorkbook, sourceWs, newName) {
  const newWs = targetWorkbook.addWorksheet(newName, {
    properties: { ...sourceWs.properties },
    views: sourceWs.views ? JSON.parse(JSON.stringify(sourceWs.views)) : undefined,
  });
  if (sourceWs.columns) {
    sourceWs.columns.forEach((col, i) => {
      if (col && col.width) newWs.getColumn(i + 1).width = col.width;
    });
  }
  const maxRow = sourceWs.rowCount;
  const maxCol = 27;
  for (let r = 1; r <= maxRow; r++) {
    const srcRow = sourceWs.getRow(r);
    const dstRow = newWs.getRow(r);
    if (srcRow.height) dstRow.height = srcRow.height;
    dstRow.hidden = !!srcRow.hidden;
    for (let c = 1; c <= maxCol; c++) {
      const srcCell = sourceWs.getCell(r, c);
      const dstCell = newWs.getCell(r, c);
      // Always copy style/number-format, even for cells with no value yet —
      // most of the template's formatting (borders, fills, fonts on
      // still-blank input cells) lives here, not on the value.
      dstCell.style = JSON.parse(JSON.stringify(srcCell.style));
      if (srcCell.numFmt) dstCell.numFmt = srcCell.numFmt;
      if (srcCell.value !== null && srcCell.value !== undefined) {
        dstCell.value = (srcCell.value && typeof srcCell.value === 'object') ? { ...srcCell.value } : srcCell.value;
      }
    }
  }
  const merges = (sourceWs.model && sourceWs.model.merges) || [];
  for (const m of merges) {
    try { newWs.mergeCells(m); } catch (e) { /* already covered */ }
  }
  // Dropdown data validations (Width Unit, Per Unit, Process Name, ...) —
  // ExcelJS keys these per cell address, so a wholesale deep-copy carries
  // every one of them over intact.
  if (sourceWs.dataValidations && sourceWs.dataValidations.model) {
    newWs.dataValidations.model = JSON.parse(JSON.stringify(sourceWs.dataValidations.model));
  }
  return newWs;
}

// Orchestrates multiple CCs (tech packs), each with one or more R3s, into
// one workbook:
//  - within a CC, the first R3 (or first R3 whose DSM-code set is new)
//    becomes that CC's base tab, named after the CC number itself
//  - each subsequent R3 in that CC whose full DSM-code set differs from
//    every group already built for that CC gets its own tab named
//    "{CC} V1", "{CC} V2", ...
//  - an R3 whose DSM-code set exactly matches a group already built for
//    that same CC is treated as a duplicate BOM and is not written anywhere
//  - ccSessions: [{ ccNumber, r3DataList: [...] }, ...] — one entry per
//    uploaded tech pack
async function buildMultiCCCostBreakDown(templateArrayBuffer, ccSessions, priceIndex) {
  const mainWorkbook = new ExcelJS.Workbook();
  await mainWorkbook.xlsx.load(templateArrayBuffer.slice(0));
  let reusableWs = mainWorkbook.getWorksheet('Format'); // consumed once, for the very first tab overall

  async function getFreshWorksheet() {
    if (reusableWs) {
      const ws = reusableWs;
      reusableWs = null;
      return { ws, isNew: false };
    }
    const tempWorkbook = new ExcelJS.Workbook();
    await tempWorkbook.xlsx.load(templateArrayBuffer.slice(0));
    return { ws: tempWorkbook.getWorksheet('Format'), isNew: true };
  }

  const usedNames = new Set();
  function uniqueName(base) {
    let name = base, n = 1;
    while (usedNames.has(name)) { name = `${base} (${++n})`; }
    usedNames.add(name);
    return name;
  }

  const report = [];
  for (const session of ccSessions) {
    // Pass 1: group every R3 in this tech pack by identical BOM (DSM-code
    // set). R3s that land in the same group are NOT split into separate
    // tabs — they all share one tab and go into that tab's R3 cell together.
    const groups = []; // { dsmSet, entries: [{ r3, data }] }
    for (const data of session.r3DataList) {
      const dsmSet = dsmSetForDecathlonData(data);
      const match = groups.find(g => dsmSetsEqual(g.dsmSet, dsmSet));
      if (match) {
        match.entries.push({ r3: data.r3, data });
      } else {
        groups.push({ dsmSet, entries: [{ r3: data.r3, data }] });
      }
    }

    // Pass 2: one tab per group — first group is the base tab (named after
    // the CC number itself), every subsequent distinct-BOM group gets its
    // own "{CC} V1", "{CC} V2", ... tab.
    let extraIndex = 0;
    for (let gi = 0; gi < groups.length; gi++) {
      const group = groups[gi];
      const isBase = gi === 0;
      const sheetName = uniqueName(isBase ? String(session.ccNumber) : `${session.ccNumber} V${++extraIndex}`);
      const r3List = group.entries.map(e => e.r3);
      const primaryData = group.entries[0].data;

      const { ws, isNew } = await getFreshWorksheet();
      const counts = fillDecathlonWorksheet(ws, primaryData, r3List, priceIndex);
      if (isNew) {
        cloneWorksheetInto(mainWorkbook, ws, sheetName);
      } else {
        ws.name = sheetName;
      }
      for (const r3 of r3List) {
        report.push({
          cc: session.ccNumber,
          r3,
          sheet: sheetName,
          status: isBase ? 'base' : 'new-tab',
          counts,
          sharedWith: r3List.length > 1 ? r3List.filter(x => x !== r3) : null,
        });
      }
    }
  }

  const buffer = await mainWorkbook.xlsx.writeBuffer();
  return { buffer, report };
}

function downloadDecathlonExtractedData(ccSessions, fileLabel) {
  const wsData = [['CC', 'R3', 'Section', 'Part (Type)', 'Designation', 'Qty', 'Unit']];
  for (const session of ccSessions) {
    for (const data of session.r3DataList) {
      for (const [section, rows] of Object.entries(data.sections)) {
        for (const r of rows) {
          wsData.push([session.ccNumber, data.r3, section, r.part, decathlonDesignation(r), r.qty, r.unit]);
        }
      }
    }
  }
  const ws = XLSX.utils.aoa_to_sheet(wsData);
  ws['!cols'] = [{ wch: 10 }, { wch: 12 }, { wch: 20 }, { wch: 26 }, { wch: 70 }, { wch: 10 }, { wch: 10 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Extracted Data');
  XLSX.writeFile(wb, `${fileLabel || 'decathlon'}_extracted.xlsx`);
}
pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";


/* ============================================================
   DECATHLON — UI WIRING
   ============================================================ */
const decathlonView = document.getElementById('decathlonView');
document.getElementById('brandDecathlon').addEventListener('click', () => {
  requestUnlock('decathlon', () => {
    homeView.hidden = true;
    decathlonView.hidden = false;
  });
});
document.getElementById('backBtnDec').addEventListener('click', () => {
  decathlonView.hidden = true;
  homeView.hidden = false;
});

const dropzoneDec = document.getElementById('dropzoneDec');
const fileInputDec = document.getElementById('fileInputDec');
const filebarDec = document.getElementById('filebarDec');
const fileNameDecEl = document.getElementById('fileNameDec');
const clearFileDec = document.getElementById('clearFileDec');
const r3Input = document.getElementById('r3Input');
const processBtnDec = document.getElementById('processBtnDec');
const processLabelDec = document.getElementById('processLabelDec');
const statusDec = document.getElementById('statusDec');
const resultsDec = document.getElementById('resultsDec');
const sessionBannerDec = document.getElementById('sessionBannerDec');
const downloadBtnDec = document.getElementById('downloadBtnDec');
const addAnotherCcBtn = document.getElementById('addAnotherCcBtn');
const cbdBtnDec = document.getElementById('cbdBtnDec');
const cbdLabelDec = document.getElementById('cbdLabelDec');
const cbdStatusDec = document.getElementById('cbdStatusDec');

let currentFileDec = null;
let currentDecResults = null;   // array of extracted+deduped R3 data for the tech pack in progress
let ccSessions = [];            // banked sessions: [{ ccNumber, r3DataList }, ...]
let decathlonPriceIndex = null; // DSM+ItemCode -> price entries, built once per session from the uploaded price list
let decathlonPriceRowCount = 0;

const priceFileInputDec = document.getElementById('priceFileInputDec');
const priceStatusDec = document.getElementById('priceStatusDec');

function parseR3List(raw) {
  return [...new Set((raw || '').split(/[\s,]+/).map(s => s.trim()).filter(Boolean))];
}

function updateProcessBtnDec() {
  processBtnDec.disabled = !(currentFileDec && parseR3List(r3Input.value).length > 0);
}

function updateSessionBanner() {
  if (ccSessions.length === 0) {
    sessionBannerDec.style.display = 'none';
    return;
  }
  sessionBannerDec.style.display = 'block';
  const ccList = ccSessions.map(s => s.ccNumber).join(', ');
  sessionBannerDec.textContent = `${ccSessions.length} tech pack${ccSessions.length > 1 ? 's' : ''} added so far — CC ${ccList}`;
}

function resetUploadFormDec() {
  currentFileDec = null;
  currentDecResults = null;
  fileInputDec.value = '';
  r3Input.value = '';
  filebarDec.classList.remove('show');
  resultsDec.classList.remove('show');
  setStatusDec('');
  updateProcessBtnDec();
}

function setFileDec(file) {
  if (!file || file.type !== 'application/pdf') {
    setStatusDec('Please choose a PDF file.', 'err');
    return;
  }
  currentFileDec = file;
  fileNameDecEl.textContent = file.name;
  filebarDec.classList.add('show');
  setStatusDec('');
  resultsDec.classList.remove('show');
  currentDecResults = null;
  updateProcessBtnDec();
}

dropzoneDec.addEventListener('dragover', e => { e.preventDefault(); dropzoneDec.classList.add('drag'); });
dropzoneDec.addEventListener('dragleave', () => dropzoneDec.classList.remove('drag'));
dropzoneDec.addEventListener('drop', e => {
  e.preventDefault(); dropzoneDec.classList.remove('drag');
  if (e.dataTransfer.files.length) setFileDec(e.dataTransfer.files[0]);
});
fileInputDec.addEventListener('change', e => {
  if (e.target.files.length) setFileDec(e.target.files[0]);
});
clearFileDec.addEventListener('click', e => {
  e.stopPropagation();
  resetUploadFormDec();
});
r3Input.addEventListener('input', updateProcessBtnDec);

if (priceFileInputDec) {
  priceFileInputDec.addEventListener('change', async e => {
    const file = e.target.files[0];
    if (!file) return;
    priceStatusDec.textContent = 'Parsing price list…';
    priceStatusDec.className = 'status';
    try {
      const rawRows = await parseDecathlonPriceFile(file);
      decathlonPriceIndex = buildDecathlonPriceIndex(rawRows);
      decathlonPriceRowCount = rawRows.length;
      priceStatusDec.textContent = `Price list loaded — ${decathlonPriceRowCount.toLocaleString()} rows indexed (${file.name})`;
      priceStatusDec.className = 'status ok';
    } catch (err) {
      console.error(err);
      decathlonPriceIndex = null;
      decathlonPriceRowCount = 0;
      priceStatusDec.textContent = 'Could not read price list: ' + err.message;
      priceStatusDec.className = 'status err';
    }
  });
}

function setStatusDec(msg, cls) {
  statusDec.textContent = msg;
  statusDec.className = 'status' + (cls ? ' ' + cls : '');
}

processBtnDec.addEventListener('click', async () => {
  if (!currentFileDec) return;
  const r3List = parseR3List(r3Input.value);
  if (r3List.length === 0) return;
  processBtnDec.disabled = true;
  processBtnDec.classList.add('loading');
  processLabelDec.textContent = 'Reading tech pack...';
  resultsDec.classList.remove('show');
  try {
    const { collected, notFound, allR3sInFile } = await extractDecathlonR3sFromFile(currentFileDec, r3List, (p, total) => {
      setStatusDec(`Scanning page ${p} of ${total}...`);
    });
    currentDecResults = collected;
    if (collected.length === 0) {
      const foundMsg = allR3sInFile.length
        ? ` R3 code(s) actually found in this PDF: ${allR3sInFile.join(', ')}`
        : ' In fact no R3 blocks were detected in this PDF at all — its layout may differ from what this tool expects.';
      setStatusDec(`Couldn't find R3(s) ${notFound.join(', ')} in this tech pack.${foundMsg}`, 'err');
    } else {
      // bank this tech pack's results immediately
      ccSessions.push({ ccNumber: collected[0].ccNumber, r3DataList: collected });
      updateSessionBanner();
      const summary = collected.map(d => `${d.r3} (${decathlonItemCount(d)} items)`).join(', ');
      let msg = `CC ${collected[0].ccNumber} — extracted ${collected.length} R3(s): ${summary}.`;
      if (notFound.length) msg += ` Not found: ${notFound.join(', ')} (R3s in this PDF: ${allR3sInFile.join(', ')}).`;
      setStatusDec(msg, notFound.length ? 'err' : 'ok');
      resultsDec.classList.add('show');
    }
  } catch (err) {
    console.error(err);
    setStatusDec('Something went wrong reading this PDF: ' + err.message, 'err');
  } finally {
    processBtnDec.disabled = false;
    processBtnDec.classList.remove('loading');
    processLabelDec.textContent = 'Extract R3(s) from Tech Pack';
    updateProcessBtnDec();
  }
});

downloadBtnDec.addEventListener('click', () => {
  if (ccSessions.length === 0) return;
  const label = ccSessions.length === 1 ? ccSessions[0].ccNumber : `${ccSessions.length}_CCs`;
  downloadDecathlonExtractedData(ccSessions, label);
});

addAnotherCcBtn.addEventListener('click', () => {
  // current tech pack's results are already banked in ccSessions — just
  // reset the form so the next tech pack can be uploaded.
  resetUploadFormDec();
  setStatusDec('Ready for the next tech pack — upload the PDF and enter its R3 number(s).', 'ok');
});

cbdBtnDec.addEventListener('click', async () => {
  if (ccSessions.length === 0) return;
  if (!decathlonPriceIndex) {
    const proceed = confirm('No price list loaded — Unit Price will be left blank (except flat-rate items like thread/labels/RFID/interlining). Continue anyway?');
    if (!proceed) return;
  }
  cbdBtnDec.disabled = true;
  cbdBtnDec.classList.add('loading');
  cbdLabelDec.textContent = 'Building Costing file...';
  cbdStatusDec.textContent = '';
  cbdStatusDec.className = 'status';
  try {
    const templateBuffer = base64ToArrayBuffer(DECATHLON_TEMPLATE_B64);
    const { buffer, report } = await buildMultiCCCostBreakDown(templateBuffer, ccSessions, decathlonPriceIndex);
    const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const ccLabel = ccSessions.length === 1 ? ccSessions[0].ccNumber : `${ccSessions.length}CCs`;
    a.download = `${ccLabel}_Costing.xlsx`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    const parts = report.map(r => {
      let line = `CC ${r.cc} R3 ${r.r3} → tab "${r.sheet}"`;
      if (r.sharedWith && r.sharedWith.length) line += ` (same BOM as R3 ${r.sharedWith.join(', ')})`;
      return line;
    });
    cbdStatusDec.textContent = `Done — ${parts.join(' | ')}`;
    cbdStatusDec.className = 'status ok';

    // session complete — clear banked state so a fresh run can start clean
    ccSessions = [];
    updateSessionBanner();
  } catch (err) {
    console.error(err);
    cbdStatusDec.textContent = 'Something went wrong building the Costing file: ' + err.message;
    cbdStatusDec.className = 'status err';
  } finally {
    cbdBtnDec.disabled = false;
    cbdBtnDec.classList.remove('loading');
    cbdLabelDec.textContent = 'Finish Uploading & Generate Costing Excel';
  }
});

